/**
 * Shared types for the explanation layer.
 *
 * This file must stay browser-safe (no imports from db or server modules):
 * the search UI imports ExplanationResult to type the /api/explain response.
 */

/**
 * Who wrote the explanation.
 * - "template": deterministic rule-based summary (free, offline, always works)
 * - "llm": text generated by an AI model via an OpenAI-compatible API
 */
export type ExplanationProvider = "template" | "llm";

export interface ExplanationResult {
  /** The explanation text itself (plain English, short). */
  text: string;
  provider: ExplanationProvider;
  /** Model name when provider is "llm", e.g. "gpt-4o-mini". */
  model: string | null;
  /** Honesty line shown under the text in the UI. */
  disclaimer: string;
  /** ISO timestamp of generation. */
  generatedAt: string;
  /**
   * Set only when an AI request was attempted and failed — tells the user
   * (and us, when debugging) why they are seeing the template instead.
   */
  fallbackReason?: string;
}

/** One opportunity reduced to the facts an explainer may mention. */
export interface ExplanationFact {
  name: string;
  category: string;
  province: string;
  /** Pre-formatted price label, e.g. "Free", "15,000 RWF", "not published". */
  priceLabel: string;
  /** Top human-readable reasons from the ranking module. */
  topReasons: string[];
  /** True for development sample records — must be flagged as unverified. */
  isSample: boolean;
}

/**
 * The "grounding pack": every fact an explainer is allowed to use.
 * Built server-side from the deterministic search outcome, so neither the
 * template nor the AI can invent facts that the pipeline didn't produce.
 */
export interface ExplanationFactPack {
  rawGoal: string;
  /** Plain-English summary of the parsed criteria. */
  criteriaSummary: string;
  facts: ExplanationFact[];
  matchedCount: number;
  scannedCount: number;
  /** Honest caveats from the search (empty when none). */
  notes: string[];
  /**
   * Optional real-world context from published NISR statistics
   * (null when unavailable). Grounds the AI in verifiable data.
   */
  tourismContext: string | null;
}
